// Expctral Prism Studio · Base Color do grafo (sem luz), fragment de quad fullscreen
struct U { resolution: vec2f, time: f32 };
@group(0) @binding(0) var<uniform> u: U;

fn prism_hash21(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453);
}

fn prism_value_noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (f * -2.0 + 3.0);
  let a = prism_hash21(i);
  let b = prism_hash21(i + vec2f(1.0, 0.0));
  let c = prism_hash21(i + vec2f(0.0, 1.0));
  let d = prism_hash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn prism_fbm(p: vec2f, octaves: i32) -> f32 {
  var sum = 0.0;
  var amp = 0.5;
  var freq = 1.0;
  for (var i = 0; i < octaves; i++) {
    sum = sum + prism_value_noise(p * freq) * amp;
    freq = freq * 2.0;
    amp = amp * 0.5;
  }
  return sum;
}

fn prism_linear_to_srgb(linear: vec3f) -> vec3f {
  let c = clamp(linear, vec3f(0.0), vec3f(1.0));
  return select(1.055 * pow(c, vec3f(1.0 / 2.4)) - 0.055, c * 12.92, c <= vec3f(0.0031308));
}

@fragment
fn fs_main(@builtin(position) fragCoord: vec4f) -> @location(0) vec4f {
  // uv do quad com v = 1 no topo, como no bake da aba 2D
  let uv = vec2f(fragCoord.x / u.resolution.x, 1.0 - fragCoord.y / u.resolution.y);
  let v0 = prism_fbm((uv * vec2f(6.0)), 4);
  let v1 = mix(vec3f(0.0030352698352941175, 0.0033465357620980074, 0.004776953478513362), vec3f(0.5775804404214573, 1.0, 0.0), vec3f(smoothstep(0.2, 0.8, v0)));
  return vec4f(prism_linear_to_srgb(v1), 1.0);
}
